const head=(ey,title,sub='',actions='')=>`<div class="page-head"><div><div class="eyebrow">${ey}</div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;
const visual=(p,cls='')=>`<div class="product-visual v${p.id%4+1} ${cls} ${p.image?'has-image':''}">${p.image?`<img src="./assets/${esc(p.image)}" alt="${esc(p.name)}" loading="lazy"/>`:`<span class="visual-ring"></span><span class="mark">${esc(p.brand==='Tehnogama'?'TG':p.brand.slice(0,2).toUpperCase())}</span>`}<span class="submark">${esc(p.brand)}</span></div>`;
const empty=(icon,title,copy,action='')=>`<div class="empty"><div class="icon-box">${I(icon,22)}</div><h3>${title}</h3><p>${copy}</p>${action}</div>`;
const productCard=p=>`<article class="card product-card" data-product="${p.id}" tabindex="0" aria-label="Otvori detalje: ${esc(p.name)}">${visual(p)}<span class="tag ${stock(p)===0?'warn':''}">${stock(p)>0?`Na stanju · ${stock(p)}`:'Na upit'}</span><div class="product-body"><span class="overline">${esc(p.brand)} · ${esc(p.sku)}</span><h3>${esc(p.name)}</h3><div class="product-meta"><span>${esc(p.cat)}</span><span>·</span><span>${esc(p.unit)}</span></div><div class="price-row"><div>${p.quote?'<strong style="font-size:13px">Cena na upit</strong>':`<strong>${money(price(p))}</strong><small>Vaša cena bez PDV-a</small>`}</div>${!p.quote?`<span class="old-price">${money(p.price)}</span>`:''}</div><div class="product-actions">${btn('Detalji',`detail:${p.id}`,'btn-outline btn-small')}${btn(p.quote?'Zatraži ponudu':'Dodaj u korpu',p.quote?`quote-product:${p.id}`:`add:${p.id}`,'btn-primary btn-small')}</div></div></article>`;
const productList=p=>`<div class="card list-product" data-product="${p.id}" tabindex="0" aria-label="Otvori detalje: ${esc(p.name)}">${visual(p)}<div><h3>${esc(p.name)}</h3><p>${esc(p.brand)} · ${esc(p.sku)} · ${esc(p.cat)}</p></div><div class="stock-col">${statusTag(stock(p)>0?'Na stanju':'Na upit')} <small class="muted">${stock(p)>0?stock(p)+' '+p.unit:''}</small></div><div class="price-row"><strong>${p.quote?'Na upit':money(price(p))}</strong></div><div class="inline">${btn('Detalji',`detail:${p.id}`,'btn-outline btn-small')}${btn(p.quote?'Ponuda':'Dodaj',p.quote?`quote-product:${p.id}`:`add:${p.id}`,'btn-primary btn-small')}</div></div>`;
function loginScreen(){return `<div class="login-shell"><div class="login-story"><div class="login-brand"><span class="brand-symbol">T</span><span><b>TEHNOGAMA</b><small>Partner Hub</small></span></div><div class="login-story-inner"><span class="login-kicker">B2B PORTAL · DEMO</span><h1>Oprema, nabavka i servis.<br><em>Na jednom mestu.</em></h1><p>Ugovoreni asortiman, brza porudžbina i pregled statusa za partnere. Tehnogama tim upravlja zahtevima i zalihama.</p><div class="login-line"><span>01 / Katalog</span><span>02 / Porudžbine</span><span>03 / Servis</span></div></div><div class="login-foot">Komprimovani vazduh · Pneumatika · Industrijska oprema</div></div><div class="login-select"><div class="login-panel"><span class="eyebrow">IZABERITE DEMO PROFIL</span><h2>Dobro došli u portal.</h2><p>Jedan klik otvara pripremljene scenarije za sastanak.</p><button class="login-option" data-act="role:airtech"><span class="login-avatar">AS</span><span><strong>AirTech Servis</strong><small>Servisni partner · ugovorene cene i ponovne kupovine</small></span>${I('arrow')}</button><button class="login-option" data-act="role:metal"><span class="login-avatar">MP</span><span><strong>Metalopromet Plus</strong><small>Industrijski kupac · različit rabat i kreditni limit</small></span>${I('arrow')}</button><button class="login-option" data-act="role:admin"><span class="login-avatar admin">TG</span><span><strong>Tehnogama tim</strong><small>Administracija · odobravanje, cene, zalihe i ERP tok</small></span>${I('arrow')}</button><div class="login-disclaimer">Interaktivni koncept. Partneri, cene, lager i porudžbine su demo podaci. Prijava je izbor profila, bez stvarne autentifikacije.</div></div></div></div>`}
function render(){if(!state.entered){document.getElementById('app').innerHTML=loginScreen();return}let nav=navItems();if(!nav.some(n=>n[0]===state.page))state.page='overview';document.getElementById('app').innerHTML=`<div class="shell"><div class="mobile-overlay ${ui.mobile?'show':''}" data-act="mobile-close"></div><aside class="sidebar ${ui.mobile?'open':''}"><div class="brand"><span class="brand-symbol">T</span><span><strong>TEHNOGAMA</strong><small>Partner Hub</small></span></div><div class="nav-group"><div class="nav-label">${state.role==='admin'?'Radni prostor':'Vaš nalog'}</div>${nav.map(([id,label,icon])=>`<button class="nav-btn ${state.page===id?'active':''}" data-act="page:${id}">${I(icon)}<span>${label}</span>${id==='quick'&&state.cart.length?`<span class="nav-count">${state.cart.reduce((a,x)=>a+x.qty,0)}</span>`:''}</button>`).join('')}</div><div class="nav-bottom"><div class="demo-note">INTERAKTIVNI KONCEPT<br>Ilustrativni podaci · lokalni demo</div><button class="nav-btn" data-act="logout">${I('close')} Odjavi se</button></div></aside><div class="main"><header class="topbar"><button class="mobile-menu" data-act="mobile-toggle" aria-label="Otvori meni">${I('menu',22)}</button><div class="breadcrumbs">Portal <span>›</span> <strong>${pageTitle()}</strong></div><div class="top-spacer"></div><div class="top-search"><input id="global-search" placeholder="Pretraži katalog po nazivu ili SKU..." aria-label="Pretraži katalog" />${I('search')}</div><button class="top-icon" data-act="${state.role==='admin'?'page:admin-orders':'cart'}" aria-label="${state.role==='admin'?'Porudžbine':'Korpa'}">${I(state.role==='admin'?'bell':'cart')}${state.role==='admin'?`<span class="bubble">${state.orders.filter(o=>o.status==='Na čekanju').length}</span>`:state.cart.length?`<span class="bubble">${state.cart.reduce((n,i)=>n+i.qty,0)}</span>`:''}</button><button class="role-switch" data-act="role-menu" aria-expanded="${ui.roleMenu}"><span class="avatar">${state.role==='admin'?'TG':partner().short.slice(0,2).toUpperCase()}</span><span class="role-name">${state.role==='admin'?'Tehnogama tim':partner().short}</span>${I('chevron',13)}</button>${ui.roleMenu?`<div class="role-menu"><button data-act="role:airtech"><span class="avatar">AS</span><span><strong>AirTech Servis</strong><small>Partner · ugovoreni uslovi</small></span></button><button data-act="role:metal"><span class="avatar">MP</span><span><strong>Metalopromet Plus</strong><small>Partner · blizu limita</small></span></button><button data-act="role:admin"><span class="avatar">TG</span><span><strong>Tehnogama tim</strong><small>Admin · obrada i ERP</small></span></button></div>`:''}</header><main class="content">${view()}</main></div></div>${ui.modal?modal():''}${ui.drawer?drawer():''}${ui.toast?`<div class="toast ${ui.toast.error?'error':''}" role="status">${esc(ui.toast.text)}</div>`:''}`}
function view(){if(state.role==='admin')return ({overview:adminOverview,'admin-orders':adminOrders,partners:adminPartners,'admin-catalog':adminCatalog,rules:adminRules,requests:adminRequests,integration:integration})[state.page]();return ({overview:overview,catalog:catalog,quick:quick,orders:orders,documents:documents,service:service})[state.page]()}
function overview(){const pa=partner(),mine=state.orders.filter(o=>o.partner===pa.id),pending=mine.filter(o=>['Na čekanju','U obradi','Potvrđeno','U transportu'].includes(o.status)),fav=[7,17,10,6];return `${head('PARTNERSKI PORTAL','Dobro došli, '+esc(pa.short),`${esc(pa.type)} · ${esc(pa.code)} · ${esc(pa.city)}`,btn(I('cart')+' Korpa', 'cart','btn-outline')+btn(I('plus')+' Nova porudžbina','page:catalog','btn-primary'))}<div class="overview-grid"><div class="welcome"><div><div class="eyebrow">OPREMA ZA VAŠ POGON</div><h2>Prava oprema. Vaši uslovi.<br>Bez čekanja na email.</h2><p>Proverite raspoloživost i ugovorene cene, pripremite porudžbinu i pratite svaki korak isporuke.</p>${btn('Istraži katalog '+I('arrow'), 'page:catalog')}</div><div class="welcome-stat"><strong>${pa.discount}%</strong><span>ugovoreni osnovni popust</span></div></div><div class="service-card"><div class="icon-box">${I('tool')}</div><div><h3>Podrška za vaš pogon</h3><p>Potrebna vam je ponuda za sistem ili servisna intervencija?</p>${btn('Pošalji zahtev', 'page:service','btn-dark')}</div></div></div><div class="grid grid-4 mt16"><div class="card stat-card"><div class="stat-icon">${I('orders')}</div><div><small>Aktivne porudžbine</small><strong>${pending.length}</strong><em>u različitim fazama</em></div></div><div class="card stat-card"><div class="stat-icon">${I('shield')}</div><div><small>Raspoloživ limit</small><strong>${money(available(pa))}</strong><em>od ${money(pa.limit)}</em></div></div><div class="card stat-card"><div class="stat-icon">${I('bolt')}</div><div><small>Vaš popust</small><strong>${pa.discount}%</strong><em>+ količinski rabat</em></div></div><div class="card stat-card"><div class="stat-icon">${I('truck')}</div><div><small>Poslednja isporuka</small><strong>${mine.find(o=>o.status==='Isporučeno')?fmtDate(mine.find(o=>o.status==='Isporučeno').date):'—'}</strong><em>pregled u porudžbinama</em></div></div></div><div class="section-head"><h2>Često naručujete</h2><button class="btn-text" data-act="page:catalog">Ceo katalog ${I('arrow',14)}</button></div><div class="catalog-grid">${fav.map(id=>productCard(P(id))).join('')}</div><div class="dashboard-bottom mt16"><div class="card card-pad"><div class="between"><strong style="font-size:14px">Poslednje porudžbine</strong><button class="btn-text" data-act="page:orders">Sve porudžbine</button></div>${mine.slice().reverse().slice(0,3).map(o=>`<div class="order-row"><div class="icon-box">${I('box')}</div><div><strong>${o.id}</strong><small>${fmtDate(o.date)} · ${o.items.reduce((n,i)=>n+i.qty,0)} kom · ${money(o.total)}</small></div>${statusTag(o.status)}</div>`).join('')}</div><div class="card card-pad"><strong style="font-size:14px">Ugovoreni uslovi</strong><p class="helper">Vaš asortiman i cene su povezani sa profilom kupca. Količinski rabat: ${state.rules.q10}% za 10+, ${state.rules.q20}% za 20+ i ${state.rules.q50}% za 50+ komada istog artikla.</p><div class="between"><span class="helper">Kreditni limit</span><strong style="font-size:12px">${money(pa.limit)}</strong></div><div class="progress mt8"><span style="width:${Math.min(100,pa.debt/pa.limit*100)}%"></span></div><p class="helper mb0">Iskorišćeno ${money(pa.debt)} · ${pa.status}</p></div></div>`}
function catalog(){const pa=partner(),cats=['Sve',...new Set(products.filter(p=>pa.allowed.includes(p.cat)).map(p=>p.cat))],brands=['Svi brendovi',...new Set(products.map(p=>p.brand))];let arr=products.filter(p=>pa.allowed.includes(p.cat)&&(!ui.category||ui.category==='Sve'||p.cat===ui.category)&&(ui.brand==='Svi brendovi'||p.brand===ui.brand)&&(ui.stock==='Sve'||(ui.stock==='Na stanju'?stock(p)>0:stock(p)===0))&&(`${p.name} ${p.sku} ${p.brand} ${p.cat}`.toLowerCase().includes(ui.search.toLowerCase())));return `${head('VAŠ ASORTIMAN','Katalog opreme','Demo cene bez PDV-a · lager i komercijalni uslovi su ilustrativni',btn(I('bolt')+' Brza porudžbina','page:quick','btn-outline')+btn(I('cart')+` Korpa (${state.cart.reduce((n,i)=>n+i.qty,0)})`,'cart','btn-primary'))}<div class="filters"><div class="filter-input">${I('search')}<input id="catalog-search" value="${esc(ui.search)}" placeholder="Naziv, SKU ili brend..." /></div><select class="select" id="brand-filter">${brands.map(b=>`<option ${ui.brand===b?'selected':''}>${esc(b)}</option>`).join('')}</select><select class="select" id="stock-filter"><option ${ui.stock==='Sve'?'selected':''}>Sve</option><option ${ui.stock==='Na stanju'?'selected':''}>Na stanju</option><option ${ui.stock==='Na upit'?'selected':''}>Na upit</option></select><div class="segmented"><button data-act="view:grid" class="${ui.view==='grid'?'active':''}" aria-label="Kartice">${I('grid')}</button><button data-act="view:list" class="${ui.view==='list'?'active':''}" aria-label="Lista">${I('list')}</button></div></div><div class="cat-chips">${cats.map(c=>`<button class="chip ${ui.category===c?'active':''}" data-act="category:${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="between" style="margin-bottom:12px"><span class="helper">${arr.length} artikala · partner: ${esc(pa.short)}</span><span class="helper">${pa.discount}% osnovno · +${state.rules.q10}% za 10+ · +${state.rules.q20}% za 20+ · +${state.rules.q50}% za 50+</span></div>${arr.length?`<div class="${ui.view==='grid'?'catalog-grid':'list-products'}">${arr.map(p=>ui.view==='grid'?productCard(p):productList(p)).join('')}</div>`:empty('search','Nema rezultata','Pokušajte drugu pretragu ili filter.',btn('Poništi filtere','clear-filters','btn-outline'))}`}
function quick(){return `${head('NARUČIVANJE','Brza porudžbina','Unesite poznati SKU ili uvezite listu artikala',btn(I('cart')+` Korpa (${state.cart.length})`,'cart','btn-primary'))}<div class="split"><div class="grid"><div class="card card-pad"><div class="between"><strong style="font-size:14px">Dodajte artikle po šifri</strong><span class="tag info">SKU + količina</span></div><p class="helper">Za servisne i nabavne timove koji već imaju spisak šifara.</p><form id="quick-form" class="quick-row"><div><label class="form-label" for="sku">Šifra artikla</label><input class="field" name="sku" id="sku" placeholder="Npr. 10125990046" required /></div><div><label class="form-label" for="quantity">Kol.</label><input class="field" name="qty" id="quantity" type="number" min="1" value="1" required /></div><button class="btn btn-primary" type="submit">${I('plus')} Dodaj</button></form><div class="line"></div><label class="form-label" for="bulk-text">Ili nalepite više redova (SKU, količina)</label><textarea class="field" id="bulk-text" placeholder="10125990046, 4&#10;10321010002, 8&#10;10932010005, 12"></textarea><div class="between mt8"><span class="helper">Zarez, tačka-zarez ili tabulator kao razdvajač.</span>${btn('Pregledaj unos','preview-paste','btn-outline btn-small')}</div></div><div class="card card-pad"><div class="between"><strong style="font-size:14px">Uvoz liste</strong><span class="tag info">CSV · TXT · XLSX · XML</span></div><p class="helper">Podržane kolone su <b>SKU</b> i <b>kolicina</b> (ili <b>qty</b>). Pre dodavanja možete proveriti pronađene artikle.</p><div class="dropzone">${I('upload')}<strong>Izaberite datoteku za pregled</strong><small>CSV, TXT, XLSX ili XML · podaci ostaju u pregledaču</small><input id="import-file" type="file" accept=".csv,.txt,.xlsx,.xml" aria-label="Izaberite datoteku" /></div><div class="between mt8"><span class="helper">Primer: <b>SKU,kolicina</b> u prvom redu</span><button class="btn-text" data-act="download-sample">Preuzmi primer CSV</button></div>${ui.importPreview.length?`<div class="line"></div><div class="between"><strong style="font-size:12px">Pregled · ${esc(ui.importName)}</strong><span class="helper">${ui.importPreview.length} redova</span></div>${ui.importPreview.map(row=>`<div class="result-item"><div style="flex:1"><strong>${esc(row.sku)}</strong><br><small>${P(row.id)?esc(P(row.id).name):'Šifra nije pronađena'}</small></div><strong>${row.qty} kom</strong>${P(row.id)?statusTag(stock(P(row.id))>0?'Na stanju':'Na upit'):statusTag('Odbijeno')}</div>`).join('')}<div class="mt16">${btn('Dodaj pronađeno u korpu','apply-import','btn-primary')}</div>`:''}</div></div><aside class="grid"><div class="card card-pad"><div class="icon-box">${I('bolt')}</div><h3 style="font-size:16px;margin:14px 0 6px">Ponovite kupovinu za minut</h3><p class="helper">Uz svaki artikl vidite cenu iz ugovora. Veća oprema za konfiguraciju ide kroz zahtev za ponudu.</p>${btn('Prethodne porudžbine','page:orders','btn-outline')}</div><div class="card card-pad"><strong style="font-size:13px">Česte šifre</strong>${[7,17,10].map(id=>{let p=P(id);return `<div class="order-row"><div style="flex:1"><strong>${p.sku}</strong><small>${esc(p.name)}</small></div><button class="btn-text" data-act="add:${p.id}">${I('plus',16)}</button></div>`}).join('')}</div><div class="card card-pad"><strong>PDF ili fotografija porudžbenice</strong><p class="helper">Dodajte dokument za ručnu proveru tima. Demo beleži naziv fajla; sadržaj se ne šalje niti čuva.</p><input class="field" id="order-attachment" type="file" accept=".pdf,image/*" aria-label="PDF ili fotografija porudžbenice" /></div><div class="notice">${I('info',16)} Uvoz i obračun su deo demonstracije; stvarne cene, lager i pravila se povezuju sa poslovnim sistemom.</div></aside></div>`}
function orders(){let mine=state.orders.filter(o=>o.partner===state.partner).slice().reverse();if(ui.orderFilter!=='Sve')mine=mine.filter(o=>o.status===ui.orderFilter);return `${head('PREGLED KUPOVINE','Moje porudžbine','Status, stavke, referenca kupca i ponovna porudžbina',btn(I('plus')+' Nova porudžbina','page:catalog','btn-primary'))}<div class="tabs">${['Sve','Na čekanju','Potvrđeno','U obradi','U transportu','Isporučeno','Odbijeno'].map(s=>`<button data-act="order-filter:${s}" class="${ui.orderFilter===s?'active':''}">${s}</button>`).join('')}</div><div class="card table-wrap"><table class="table"><thead><tr><th>Porudžbina</th><th>Datum</th><th>Stavke</th><th>Referenca</th><th>Iznos</th><th>Status</th><th></th></tr></thead><tbody>${mine.map(o=>`<tr><td><strong>${o.id}</strong></td><td>${fmtDate(o.date)}</td><td>${o.items.reduce((n,i)=>n+i.qty,0)} kom · ${o.items.length} artikla</td><td>${esc(o.po)}</td><td><strong>${money(o.total)}</strong></td><td>${statusTag(o.status)}</td><td><button class="btn-text" data-act="order:${o.id}">Detalji</button></td></tr>`).join('')||'<tr><td colspan="7">Nema porudžbina sa izabranim statusom.</td></tr>'}</tbody></table></div>`}
function documents(){let mine=state.orders.filter(o=>o.partner===state.partner&&o.status==='Isporučeno').slice().reverse();return `${head('DOKUMENTACIJA','Dokumenti i istorija','Primer dokumentacije dostupne partneru u jednom mestu')}<div class="split"><div class="card card-pad"><div class="between"><strong style="font-size:14px">Isporučene porudžbine</strong><span class="tag info">Demo izvoz</span></div>${mine.map(o=>`<div class="invoice-box">${I('file')}<div><strong>Pregled porudžbine ${o.id}</strong><small>${fmtDate(o.date)} · ${money(o.total)}</small></div><button class="file-link btn-text" data-act="download-order:${o.id}">Preuzmi CSV</button></div>`).join('')||empty('file','Još nema dokumenata','Dokumenti će se pojaviti nakon isporuke.')}<div class="notice mt16">Računi, otpremnice i sertifikati bi se ovde preuzimali iz poslovnog sistema. Ovaj demo izvozi ilustrativni pregled porudžbine.</div></div><div class="grid"><div class="card card-pad"><div class="icon-box">${I('file')}</div><h3 style="font-size:15px">Tehnički listovi</h3><p class="helper">Otvorite artikl u katalogu za pregled ključnih parametara i preuzimanje demo tehničkog lista.</p>${btn('Otvori katalog','page:catalog','btn-outline')}</div><div class="card card-pad"><div class="icon-box">${I('tool')}</div><h3 style="font-size:15px">Servisna istorija</h3><p class="helper">Vaši zahtevi i status intervencije na jednom mestu.</p>${state.requests.filter(r=>r.partner===state.partner).map(r=>`<div class="order-row"><div><strong>${r.id} · ${esc(r.subject)}</strong><small>${fmtDate(r.date)}</small></div>${statusTag(r.status)}</div>`).join('')||'<p class="helper">Nema otvorenih zahteva.</p>'}</div></div></div>`}
function service(){let mine=state.requests.filter(r=>r.partner===state.partner).slice().reverse();return `${head('INŽENJERSKA PODRŠKA','Ponuda i servis','Oprema po projektu i podrška za postojeći sistem')}<div class="grid grid-2"><div class="card card-pad"><div class="icon-box">${I('box')}</div><h2 style="font-size:17px;margin:15px 0 5px">Zahtev za ponudu</h2><p class="helper">Opišite primenu, traženi pritisak i protok. Tim može pripremiti konfiguraciju opreme.</p>${btn('Nova ponuda','quote','btn-primary')}</div><div class="card card-pad"><div class="icon-box">${I('tool')}</div><h2 style="font-size:17px;margin:15px 0 5px">Servisna prijava</h2><p class="helper">Pošaljite model opreme, lokaciju i opis problema u jednom zahtevu.</p>${btn('Prijavi servis','service-form','btn-dark')}</div></div><div class="section-head"><h2>Vaši zahtevi</h2><span>${mine.length} ukupno</span></div><div class="card table-wrap"><table class="table"><thead><tr><th>Broj</th><th>Vrsta</th><th>Predmet</th><th>Datum</th><th>Status</th></tr></thead><tbody>${mine.map(r=>`<tr><td><strong>${r.id}</strong></td><td>${r.type}</td><td>${esc(r.subject)}<span class="sub">${esc(r.detail)}</span></td><td>${fmtDate(r.date)}</td><td>${statusTag(r.status)}</td></tr>`).join('')||'<tr><td colspan="5">Još nema zahteva.</td></tr>'}</tbody></table></div>`}
function adminOverview(){let pending=state.orders.filter(o=>o.status==='Na čekanju'),req=state.requests.filter(r=>['Novo','U pripremi'].includes(r.status));return `${head('OPERATIVNI PREGLED','Dobro došli, Tehnogama tim','Porudžbine, partneri i zahtevi na jednom mestu',btn(I('refresh')+' ERP tok','page:integration','btn-outline')+btn(I('orders')+' Obradi porudžbine','page:admin-orders','btn-primary'))}<div class="admin-banner"><div class="icon-box">${I('info')}</div><div><strong>Prikaz predviđenog procesa</strong><p>Odobravanje i ERP sinhronizacija su simulirani. Cene, zalihe i kupci su ilustrativni.</p></div>${btn('Kako radi','page:integration','btn-outline btn-small')}</div><div class="grid grid-4"><div class="card stat-card"><div class="stat-icon">${I('clock')}</div><div><small>Čeka odobrenje</small><strong>${pending.length}</strong><em>porudžbina</em></div></div><div class="card stat-card"><div class="stat-icon">${I('users')}</div><div><small>Partneri</small><strong>${state.partners.length}</strong><em>demo profila</em></div></div><div class="card stat-card"><div class="stat-icon">${I('tool')}</div><div><small>Otvoreni zahtevi</small><strong>${req.length}</strong><em>ponude i servis</em></div></div><div class="card stat-card"><div class="stat-icon">${I('refresh')}</div><div><small>Čeka ERP</small><strong>${state.orders.filter(o=>o.erp==='Čeka slanje').length}</strong><em>odobrene porudžbine</em></div></div></div><div class="dashboard-bottom mt16"><div class="card card-pad"><div class="between"><strong style="font-size:14px">Zahteva pažnju</strong><button class="btn-text" data-act="page:admin-orders">Sve porudžbine</button></div>${pending.slice().reverse().slice(0,5).map(o=>`<div class="order-row"><div class="icon-box">${I('orders')}</div><div style="flex:1"><strong>${o.id} · ${esc(state.partners.find(p=>p.id===o.partner)?.short||'Partner')}</strong><small>${fmtDate(o.date)} · ${money(o.total)} · ${esc(o.po)}</small></div><button class="btn btn-outline btn-small" data-act="order:${o.id}">Pregled</button></div>`).join('')||empty('check','Sve je obrađeno','Nema porudžbina koje čekaju pregled.')}</div><div class="card card-pad"><strong style="font-size:14px">Tok od kupca do isporuke</strong><div class="activity mt16"><div><strong>1. Kupac šalje porudžbinu</strong>Ugovorena cena, lager i limit se proveravaju.</div><div><strong>2. Tim potvrđuje zahtev</strong>Izuzeci se zadržavaju na ručnom pregledu.</div><div><strong>3. Slanje u ERP</strong>Demo prikazuje status sinhronizacije.</div><div><strong>4. Status nazad u portal</strong>Kupac prati obradu i isporuku.</div></div></div></div><div class="section-head"><h2>Partneri na koje treba obratiti pažnju</h2><button class="btn-text" data-act="page:partners">Pregled partnera ${I('arrow',14)}</button></div><div class="grid grid-3">${state.partners.map(pa=>`<div class="card card-pad"><div class="between"><strong style="font-size:12px">${esc(pa.name)}</strong>${statusTag(pa.status)}</div><p class="helper">${esc(pa.type)} · ${esc(pa.city)}</p><div class="between"><span class="helper">Iskorišćen limit</span><strong style="font-size:11px">${Math.round(pa.debt/pa.limit*100)}%</strong></div><div class="progress mt8"><span style="width:${Math.min(100,pa.debt/pa.limit*100)}%;background:${pa.debt>pa.limit?'#df806b':pa.debt/pa.limit>.8?'#e5ac60':'#22a3ad'}"></span></div></div>`).join('')}</div>`}
function adminOrders(){let arr=state.orders.slice().reverse().filter(o=>ui.adminOrderFilter==='Sve'||o.status===ui.adminOrderFilter);return `${head('OPERATIVA','Porudžbine partnera','Pregledajte, potvrdite i pratite simulirani ERP status')}<div class="tabs">${['Sve','Na čekanju','Potvrđeno','U obradi','U transportu','Isporučeno','Odbijeno'].map(s=>`<button data-act="admin-order-filter:${s}" class="${ui.adminOrderFilter===s?'active':''}">${s} ${s==='Na čekanju'?`(${state.orders.filter(o=>o.status===s).length})`:''}</button>`).join('')}</div><div class="card table-wrap"><table class="table"><thead><tr><th>Broj</th><th>Partner</th><th>Datum</th><th>Referenca</th><th>Vrednost</th><th>Status</th><th>ERP</th><th></th></tr></thead><tbody>${arr.map(o=>`<tr><td><strong>${o.id}</strong></td><td>${esc(state.partners.find(p=>p.id===o.partner)?.short||'—')}</td><td>${fmtDate(o.date)}</td><td>${esc(o.po)}</td><td><strong>${money(o.total)}</strong></td><td>${statusTag(o.status)}</td><td>${statusTag(o.erp)}</td><td><button class="btn-text" data-act="order:${o.id}">Obradi</button></td></tr>`).join('')||'<tr><td colspan="8">Nema rezultata.</td></tr>'}</tbody></table></div>`}
function adminPartners(){return `${head('PARTNERSKA MREŽA','Partneri i uslovi','Ugovorene cene, odobreni asortiman i limit po kupcu')}<div class="grid grid-3">${state.partners.map(pa=>`<div class="card card-pad"><div class="between"><span class="avatar" style="width:39px;height:39px">${esc(pa.short.slice(0,2).toUpperCase())}</span>${statusTag(pa.status)}</div><h3 style="font-size:15px;margin:15px 0 3px">${esc(pa.name)}</h3><div class="helper">${esc(pa.code)} · ${esc(pa.city)}<br>${esc(pa.contact)} · ${esc(pa.type)}</div><div class="line"></div><div class="between"><span class="helper">Osnovni popust</span><strong>${pa.discount}%</strong></div><div class="between mt8"><span class="helper">Limit / raspoloživo</span><strong style="font-size:11px">${money(pa.limit)} / ${money(available(pa))}</strong></div><div class="progress mt16"><span style="width:${Math.min(100,pa.debt/pa.limit*100)}%"></span></div><div class="between mt16">${btn('Uredi uslove',`partner:${pa.id}`,'btn-outline btn-small')}${btn('Prikaži kao kupac',`role:${pa.id}`,'btn-soft btn-small')}</div></div>`).join('')}</div>`}
function adminCatalog(){let low=products.filter(p=>stock(p)<10);return `${head('ARTIKLI I ZALIHE','Katalog i zalihe','Demo pregled: ažurirajte lager i proverite kako ga partner vidi',btn(I('refresh')+' Simuliraj osvežavanje','sync-stock','btn-outline'))}<div class="grid grid-3"><div class="card stat-card"><div class="stat-icon">${I('box')}</div><div><small>Artikli u katalogu</small><strong>${products.length}</strong><em>${new Set(products.map(p=>p.cat)).size} kategorija</em></div></div><div class="card stat-card"><div class="stat-icon">${I('clock')}</div><div><small>Niske zalihe</small><strong>${low.length}</strong><em>ispod 10 komada</em></div></div><div class="card stat-card"><div class="stat-icon">${I('info')}</div><div><small>Na upit</small><strong>${products.filter(p=>p.quote).length}</strong><em>projektna oprema</em></div></div></div><div class="card card-pad mt16"><div class="between"><strong>Uvoz zaliha po šifri</strong><span class="tag info">CSV · TXT · XLSX · XML</span></div><p class="helper">Prva kolona SKU, druga raspoloživa količina. Pregledajte pronađene artikle pre primene.</p><input class="field" id="stock-import-file" type="file" accept=".csv,.txt,.xlsx,.xml" aria-label="Uvoz zaliha" /><button class="btn-text mt8" data-act="download-stock-sample">Preuzmi primer CSV</button>${ui.stockPreview.length?`<div class="line"></div><strong>Pregled · ${esc(ui.stockImportName)}</strong>${ui.stockPreview.map(x=>`<div class="result-item"><div style="flex:1"><strong>${esc(x.sku)}</strong><br><small>${x.id?esc(P(x.id).name):'Šifra nije pronađena'}</small></div><strong>${x.qty} kom</strong></div>`).join('')}${btn('Primeni pronađene zalihe','apply-stock-import','btn-primary mt16')}</div>`:'</div>'}<div class="card table-wrap mt16"><table class="table"><thead><tr><th>Artikal</th><th>Brend</th><th>Kategorija</th><th>Osnovna cena</th><th>Lager</th><th>Vidljivost</th><th></th></tr></thead><tbody>${products.map(p=>`<tr><td><strong>${esc(p.name)}</strong><span class="sub">${esc(p.sku)}</span></td><td>${esc(p.brand)}</td><td>${esc(p.cat)}</td><td>${p.quote?'Na upit':money(p.price)}</td><td>${stock(p)} ${esc(p.unit)}</td><td>${statusTag(stock(p)>0?'Na stanju':'Na upit')}</td><td><button class="btn-text" data-act="stock:${p.id}">Uredi</button></td></tr>`).join('')}</tbody></table></div>`}
function adminRules(){let r=state.rules;return `${head('KOMERCIJALNA PRAVILA','Cene i pravila','Količinski rabati i ugovoreni uslovi partnera u demonstracionom cenovniku')}<div class="split"><div class="card card-pad"><div class="between"><strong>Količinski rabati</strong><span class="tag info">Po artiklu</span></div><p class="helper">Dodatni rabat se obračunava preko osnovnog popusta partnera. Promena odmah utiče na katalog i korpu.</p><form id="rules-form" class="form-grid"><div><label class="form-label">10+ komada (%)</label><input class="field" name="q10" type="number" min="0" max="50" value="${r.q10}" required></div><div><label class="form-label">20+ komada (%)</label><input class="field" name="q20" type="number" min="0" max="50" value="${r.q20}" required></div><div><label class="form-label">50+ komada (%)</label><input class="field" name="q50" type="number" min="0" max="50" value="${r.q50}" required></div><div class="align-bottom"><button class="btn btn-primary" type="submit">Sačuvaj pravila</button></div></form><div class="notice mt16">Na primer, 20 komada artikla obračunava osnovni popust partnera i dodatnih ${r.q20}% količinskog rabata.</div></div><div class="card card-pad"><strong>Partneri i limit</strong><p class="helper">Odaberite partnera da promenite njegov osnovni rabat, kreditni limit i status.</p>${state.partners.map(pa=>`<div class="order-row"><span class="avatar">${esc(pa.short.slice(0,2))}</span><div style="flex:1"><strong>${esc(pa.short)}</strong><small>${pa.discount}% osnovni · ${money(available(pa))} raspoloživo</small></div><button class="btn-text" data-act="partner:${pa.id}">Uredi</button></div>`).join('')}</div></div>`}
function adminRequests(){return `${head('KOMERCIJALA I SERVIS','Zahtevi partnera','Ponude za opremu i servisne prijave')}<div class="grid grid-3">${state.requests.slice().reverse().map(r=>`<div class="card card-pad"><div class="between"><span class="tag ${r.type==='Servis'?'info':''}">${esc(r.type)}</span>${statusTag(r.status)}</div><h3 style="font-size:14px;line-height:1.4;margin:16px 0 5px">${esc(r.subject)}</h3><p class="helper">${esc(state.partners.find(p=>p.id===r.partner)?.name||'—')} · ${fmtDate(r.date)}</p><p class="helper" style="min-height:38px">${esc(r.detail)}</p><div class="line"></div>${btn('Otvori zahtev',`request:${r.id}`,'btn-outline btn-small')}</div>`).join('')}</div>`}
function integration(){return `${head('POVEZIVANJE','Predviđeni ERP tok','Prikaz šta portal čita i šta prosleđuje poslovnom sistemu')}<div class="admin-banner"><div class="icon-box">${I('refresh')}</div><div><strong>Demo simulacija · nema aktivne veze sa ERP-om</strong><p>Tačan ERP, dostupni interfejsi i učestalost razmene utvrđuju se na tehničkoj radionici.</p></div></div><div class="grid grid-3"><div class="card card-pad"><div class="icon-box">${I('download')}</div><h3 style="font-size:15px">ERP → Portal</h3><p class="helper">Artikli, šifre, raspoloživost po skladištu, partneri, ugovorne cene, limiti, dokumenti i statusi.</p></div><div class="card card-pad"><div class="icon-box">${I('upload')}</div><h3 style="font-size:15px">Portal → ERP</h3><p class="helper">Porudžbine i stavke, referenca kupca, adresa isporuke, zahtevi za ponudu i servis.</p></div><div class="card card-pad"><div class="icon-box">${I('shield')}</div><h3 style="font-size:15px">Kontrola izuzetaka</h3><p class="helper">Limit, neodobreni artikli i manjak zaliha zadržavaju zahtev na pregledu pre potvrde.</p></div></div><div class="section-head"><h2>Red za slanje</h2><span>Ručno pokrenite simulaciju</span></div><div class="card table-wrap"><table class="table"><thead><tr><th>Porudžbina</th><th>Partner</th><th>Status</th><th>ERP status</th><th>Radnja</th></tr></thead><tbody>${state.orders.slice().reverse().filter(o=>o.status!=='Odbijeno').map(o=>`<tr><td><strong>${o.id}</strong></td><td>${esc(state.partners.find(p=>p.id===o.partner)?.short||'—')}</td><td>${statusTag(o.status)}</td><td>${statusTag(o.erp)}</td><td>${o.erp==='Čeka slanje'?btn('Pošalji u ERP',`sync:${o.id}`,'btn-primary btn-small'):'<span class="muted">—</span>'}</td></tr>`).join('')}</tbody></table></div><p class="helper">Klik na „Pošalji u ERP“ menja samo lokalni demo status. Ne šalje podatke spoljnim sistemima.</p>`}
function modal(){let m=ui.modal,body='',title='',ey='DETALJI';if(m.type==='product'){let p=P(m.id);title=p.name;ey=`${p.brand} · ${p.sku}`;body=`<div class="detail-grid">${visual(p,'detail-visual')}<div><span class="tag ${stock(p)?'':'warn'}">${stock(p)?`Na stanju · ${stock(p)} ${p.unit}`:'Dostupnost na upit'}</span><h3 class="detail-section-title">Opis proizvoda</h3><div class="detail-description"><p>${esc(p.desc)}</p><p>${esc(detailGuide[p.cat]||'Proverite tehničke karakteristike pre naručivanja.')}</p></div><div class="price-row"><div>${p.quote?'<strong>Cena na upit</strong>':`<strong style="font-size:22px">${money(price(p))}</strong><small>Ugovorena cena bez PDV-a · ${partner().discount}% popust</small>`}</div></div><div class="line"></div><h3 class="detail-section-title">Tehničke karakteristike</h3><div class="spec">${Object.entries(p.spec).map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}<div><span>Šifra</span><strong>${esc(p.sku)}</strong></div><div><span>Brend</span><strong>${esc(p.brand)}</strong></div></div><div class="inline wrap mt16">${btn(p.quote?'Zatraži ponudu':'Dodaj u korpu',p.quote?`quote-product:${p.id}`:`add:${p.id}`,'btn-primary')}${btn(I('download')+' Tehnički list',`download-spec:${p.id}`,'btn-outline')}</div><p class="helper">Komercijalni podaci su demo. ${p.sku.startsWith('DEMO-')?'Šifra je demo. ':''}<a href="${esc(p.source)}" target="_blank" rel="noopener noreferrer" class="source-link">Izvorni artikal ↗</a></p></div></div>`}
if(m.type==='order'){let o=state.orders.find(x=>x.id===m.id),pa=state.partners.find(p=>p.id===o.partner);title=o.id;ey=`PORUDŽBINA · ${fmtDate(o.date)}`;let warning=pa.status==='Blokiran'||o.total>available(pa);body=`<div class="between wrap"><div><strong style="font-size:13px">${esc(pa.name)}</strong><div class="helper">${esc(pa.code)} · Referenca ${esc(o.po)}</div></div>${statusTag(o.status)}</div><div class="line"></div><div class="table-wrap"><table class="table"><thead><tr><th>Artikal</th><th>SKU</th><th>Kol.</th></tr></thead><tbody>${o.items.map(i=>`<tr><td><strong>${esc(P(i.id)?.name||'Artikal')}</strong></td><td>${esc(P(i.id)?.sku||'—')}</td><td>${i.qty}</td></tr>`).join('')}</tbody></table></div><div class="summary-line total"><span>Ukupno bez PDV-a</span><strong>${money(o.total)}</strong></div><div class="between"><span class="helper">ERP tok</span>${statusTag(o.erp)}</div>${warning&&o.status==='Na čekanju'?`<div class="notice warn mt16">${pa.status==='Blokiran'?'Partner je blokiran. ':''}Porudžbina prelazi raspoloživ limit ili zahteva ručni pregled. Admin može odobriti izuzetak.</div>`:''}${o.note?`<p class="helper"><b>Napomena:</b> ${esc(o.note)}</p>`:''}<div class="line"></div><div class="inline wrap">${state.role==='admin'?`${o.status==='Na čekanju'?btn(warning?'Odobri uz izuzetak':'Potvrdi porudžbinu',`order-status:${o.id}:Potvrđeno`,'btn-primary')+btn('Odbij',`order-status:${o.id}:Odbijeno`,'btn-danger'):''}${o.status==='Potvrđeno'?btn('Pošalji u obradu',`order-status:${o.id}:U obradi`,'btn-primary'):''}${o.status==='U obradi'?btn('Označi u transportu',`order-status:${o.id}:U transportu`,'btn-primary'):''}${o.status==='U transportu'?btn('Označi isporučeno',`order-status:${o.id}:Isporučeno`,'btn-primary'):''}${o.erp==='Čeka slanje'?btn('Pošalji u ERP',`sync:${o.id}`,'btn-outline'):''}`:btn(I('refresh')+' Ponovi porudžbinu',`reorder:${o.id}`,'btn-primary')}</div>`}
if(m.type==='partner'){let pa=state.partners.find(p=>p.id===m.id);title=pa.name;ey='USLOVI PARTNERA';body=`<form id="partner-form" data-id="${pa.id}"><div class="form-grid"><div><label class="form-label">Osnovni popust (%)</label><input class="field" name="discount" type="number" min="0" max="60" value="${pa.discount}" required /></div><div><label class="form-label">Kreditni limit (RSD)</label><input class="field" name="limit" type="number" min="0" value="${pa.limit}" required /></div><div><label class="form-label">Trenutno zaduženje (RSD)</label><input class="field" name="debt" type="number" min="0" value="${pa.debt}" required /></div><div><label class="form-label">Status</label><select class="field" name="status">${['Aktivan','Blizu limita','Blokiran'].map(x=>`<option ${pa.status===x?'selected':''}>${x}</option>`).join('')}</select></div></div><p class="helper">Izmena ugovorenog popusta odmah menja cene u partnerskom katalogu. Iznosi su demo podaci.</p><button type="submit" class="btn btn-primary">Sačuvaj uslove</button></form>`}
if(m.type==='stock'){let p=P(m.id);title=p.name;ey='IZMENA ZALIHA';body=`<form id="stock-form" data-id="${p.id}"><p class="helper">${esc(p.sku)} · trenutno: ${stock(p)} ${esc(p.unit)}</p><label class="form-label">Raspoloživo za poručivanje</label><input class="field" name="stock" type="number" min="0" value="${stock(p)}" required /><p class="helper">Novo stanje vide i kupac i admin u ovom pregledaču.</p><button type="submit" class="btn btn-primary">Sačuvaj lager</button></form>`}
if(m.type==='quote'){title='Zahtev za ponudu';ey='OPREMA PO VAŠOJ MERI';let p=m.id?P(m.id):null;body=`<form id="quote-form"><div class="form-grid"><div class="full"><label class="form-label">Predmet upita</label><input class="field" name="subject" value="${p?esc(p.name):''}" placeholder="Npr. vijčani kompresor za novi pogon" required /></div><div><label class="form-label">Radni pritisak</label><input class="field" name="pressure" placeholder="Npr. 8 bar" /></div><div><label class="form-label">Potreban protok</label><input class="field" name="flow" placeholder="Npr. 1,2 m³/min" /></div><div><label class="form-label">Planirani rok</label><select class="field" name="timeline"><option>U narednih 30 dana</option><option>1–3 meseca</option><option>Kasnije / planiranje</option></select></div><div><label class="form-label">Lokacija</label><input class="field" name="location" placeholder="Grad / pogon" /></div><div class="full"><label class="form-label">Primena i dodatni uslovi</label><textarea class="field" name="details" placeholder="Radni režim, postojeća oprema, zahtevi za kvalitet vazduha..."></textarea></div></div><div class="notice">Demo zahtev će se pojaviti i u administrativnom prikazu. Ne šalje se Tehnogami.</div><button type="submit" class="btn btn-primary mt16">Pošalji demo zahtev</button></form>`}
if(m.type==='service'){title='Prijava servisa';ey='TEHNIČKA PODRŠKA';body=`<form id="service-form"><div class="form-grid"><div><label class="form-label">Model opreme</label><input class="field" name="model" placeholder="Npr. ABAC PRO A29B" required /></div><div><label class="form-label">Serijski broj</label><input class="field" name="serial" placeholder="Ako je poznat" /></div><div><label class="form-label">Lokacija pogona</label><input class="field" name="location" placeholder="Grad i adresa" required /></div><div><label class="form-label">Prioritet</label><select class="field" name="priority"><option>Redovan</option><option>Visok · zastoj u proizvodnji</option></select></div><div class="full"><label class="form-label">Opis zahteva</label><textarea class="field" name="details" placeholder="Simptomi, vreme pojave, potrebna intervencija..." required></textarea></div><div class="full"><label class="form-label">Fotografija / dokument (opciono)</label><input class="field" name="attachment" type="file" accept="image/*,.pdf" /><span class="helper">U demou se čuva samo naziv datoteke, bez slanja fajla.</span></div></div><div class="notice">Ova prijava ostaje samo u lokalnom demou.</div><button type="submit" class="btn btn-primary mt16">Kreiraj demo prijavu</button></form>`}
if(m.type==='request'){let r=state.requests.find(x=>x.id===m.id);title=r.id;ey=r.type.toUpperCase();body=`<p><strong>${esc(r.subject)}</strong></p><p class="helper">${esc(state.partners.find(p=>p.id===r.partner)?.name||'—')} · ${fmtDate(r.date)}</p><div class="notice">${esc(r.detail)}</div><div class="between mt16"><span class="helper">Status</span>${statusTag(r.status)}</div><div class="inline wrap mt16">${r.status==='Novo'?btn(r.type==='Servis'?'Zakaži servis':'Pripremi ponudu',`request-status:${r.id}:${r.type==='Servis'?'Zakazano':'U pripremi'}`,'btn-primary'):''}${r.status==='U pripremi'?btn('Označi ponuđeno',`request-status:${r.id}:Ponuda poslata`,'btn-primary'):''}${r.status==='Zakazano'?btn('Označi završeno',`request-status:${r.id}:Završeno`,'btn-primary'):''}</div>`}
return `<div class="modal-layer" data-act="close-overlay"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><div class="eyebrow">${ey}</div><h2>${esc(title)}</h2></div><button class="icon-btn" data-act="close" aria-label="Zatvori">${I('close',20)}</button></div><div class="modal-body">${body}</div></div></div>`}
function drawer(){let pa=partner(),subtotal=state.cart.reduce((s,i)=>s+price(P(i.id),pa,i.qty)*i.qty,0),shortage=state.cart.filter(i=>i.qty>stock(P(i.id)));return `<div class="drawer-layer" data-act="close-overlay"><aside class="drawer" role="dialog" aria-modal="true" aria-label="Korpa"><div class="modal-head"><div><div class="eyebrow">VAŠA NARUDŽBINA</div><h2>Korpa · ${state.cart.reduce((n,i)=>n+i.qty,0)} kom</h2></div><button class="icon-btn" data-act="close" aria-label="Zatvori">${I('close',20)}</button></div><div class="drawer-body">${state.cart.length?`${state.cart.map(i=>{let p=P(i.id);return `<div class="cart-item">${visual(p)}<div><strong>${esc(p.name)}</strong><small>${esc(p.sku)} · ${money(price(p,pa,i.qty))} / kom</small></div><div class="qty"><button data-act="cart-minus:${p.id}">−</button><input aria-label="Količina ${esc(p.name)}" type="number" min="1" value="${i.qty}" data-qty="${p.id}"/><button data-act="cart-plus:${p.id}">+</button></div><strong class="line-total" style="font-size:11px">${money(price(p,pa,i.qty)*i.qty)}</strong><button class="icon-btn" data-act="cart-remove:${p.id}" aria-label="Ukloni">${I('trash',16)}</button></div>`}).join('')}<div class="summary-line"><span>Ugovoreni popust</span><strong>${pa.discount}%</strong></div><div class="summary-line"><span>Količinski popust</span><strong>${state.rules.q10}% / 10+, ${state.rules.q20}% / 20+, ${state.rules.q50}% / 50+</strong></div><div class="summary-line total"><span>Ukupno bez PDV-a</span><strong>${money(subtotal)}</strong></div>${shortage.length?`<div class="notice warn">Za ${shortage.map(i=>esc(P(i.id).sku)).join(', ')} nema dovoljno zaliha. Smanjite količinu pre slanja.</div>`:''}${pa.status==='Blokiran'||subtotal>available(pa)?`<div class="notice warn mt8">${pa.status==='Blokiran'?'Partner je blokiran. ':''}Iznos prelazi raspoloživi limit (${money(available(pa))}). Zahtev će čekati ručno odobrenje.</div>`:''}<div class="line"></div><form id="checkout-form"><div class="form-row"><label class="form-label">Vaša referenca / PO broj</label><input class="field" name="po" placeholder="Npr. NAB-2026-041" required /></div><div class="form-row"><label class="form-label">Isporuka</label><select class="field" name="delivery"><option>Adresa iz profila · ${esc(pa.city)}</option><option>Preuzimanje · Šimanovci</option></select></div><div class="form-row"><label class="form-label">Napomena (opciono)</label><textarea class="field" name="note" placeholder="Uputstvo za isporuku, kontakt..."></textarea></div><button type="submit" class="btn btn-primary" style="width:100%" ${shortage.length?'disabled':''}>Pošalji demo porudžbinu</button><p class="helper">Porudžbina se čuva lokalno; ne šalje se Tehnogami.</p></form>`:empty('cart','Korpa je prazna','Dodajte artikle iz kataloga ili brze porudžbine.',btn('Otvori katalog','page:catalog','btn-primary'))}</div></aside></div>`}
function toast(text,error=false){ui.toast={text,error};render();clearTimeout(toast.timer);toast.timer=setTimeout(()=>{ui.toast=null;document.querySelector('.toast')?.remove()},3500)}
function add(id,qty=1,silent=false){let p=P(id);if(!p||p.quote){if(!silent)toast('Za ovu opremu pošaljite zahtev za ponudu.',true);return false}qty=Math.max(1,Number(qty)||1);let existing=state.cart.find(i=>i.id===p.id),total=(existing?.qty||0)+qty;if(total>stock(p)){if(!silent)toast(`Dostupno je ${stock(p)} kom za ${p.sku}.`,true);return false}existing?existing.qty=total:state.cart.push({id:p.id,qty});save();if(!silent)toast(`${p.name} dodat u korpu.`);return true}
function download(name,content,type='text/plain;charset=utf-8'){let blob=new Blob(['\ufeff',content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
function docSpec(p){return `TEHNOGAMA PARTNER HUB — ILUSTRATIVNI TEHNIČKI LIST\n\n${p.name}\nSKU: ${p.sku}\nBrend: ${p.brand}\nKategorija: ${p.cat}\n\n${p.desc}\n\n${Object.entries(p.spec).map(([k,v])=>`${k}: ${v}`).join('\n')}\n\nOvo je demo dokument; podatke potvrditi iz zvanične dokumentacije proizvođača.`}
function orderCsv(o){return ['SKU;Artikal;Kolicina',...o.items.map(i=>`${P(i.id)?.sku||''};${P(i.id)?.name||''};${i.qty}`),`Ukupno bez PDV-a;${o.total};RSD`,`Status;${o.status};`,`Referenca;${o.po};`].join('\n')}
document.addEventListener('click',e=>{let el=e.target.closest('[data-act]');if(!el){let card=e.target.closest('[data-product]');if(card){ui.modal={type:'product',id:+card.dataset.product};render()}return}let a=el.dataset.act;if(a==='close-overlay'&&e.target!==el)return;if(a==='close'||a==='close-overlay'){ui.modal=null;ui.drawer=null;render();return}if(a==='mobile-toggle'||a==='mobile-close'){ui.mobile=a==='mobile-toggle'?!ui.mobile:false;render();return}if(a==='role-menu'){ui.roleMenu=!ui.roleMenu;render();return}if(a.startsWith('role:')){let id=a.slice(5);state.entered=true;state.role=id==='admin'?'admin':'partner';if(id!=='admin')state.partner=id;state.page='overview';state.cart=[];ui.roleMenu=false;ui.mobile=false;ui.modal=null;ui.drawer=null;ui.search='';ui.category='Sve';save();render();return}if(a.startsWith('page:')){state.page=a.slice(5);ui.mobile=false;ui.roleMenu=false;ui.modal=null;ui.drawer=null;save();render();window.scrollTo(0,0);return}if(a==='logout'){state.entered=false;ui.modal=null;ui.drawer=null;ui.roleMenu=false;ui.mobile=false;save();render();return}if(a==='cart'){ui.drawer='cart';render();return}if(a==='clear-filters'){ui.search='';ui.category='Sve';ui.brand='Svi brendovi';ui.stock='Sve';render();return}if(a.startsWith('category:')){ui.category=a.slice(9);render();return}if(a.startsWith('view:')){ui.view=a.slice(5);render();return}if(a.startsWith('order-filter:')){ui.orderFilter=a.slice(13);render();return}if(a.startsWith('admin-order-filter:')){ui.adminOrderFilter=a.slice(19);render();return}if(a.startsWith('detail:')){ui.modal={type:'product',id:+a.slice(7)};render();return}if(a.startsWith('add:')){add(+a.slice(4));return}if(a.startsWith('quote-product:')){ui.modal={type:'quote',id:+a.slice(14)};render();return}if(a==='quote'||a==='service-form'){ui.modal={type:a==='quote'?'quote':'service'};render();return}if(a.startsWith('order:')){ui.modal={type:'order',id:a.slice(6)};render();return}if(a.startsWith('partner:')){ui.modal={type:'partner',id:a.slice(8)};render();return}if(a.startsWith('stock:')){ui.modal={type:'stock',id:+a.slice(6)};render();return}if(a.startsWith('request:')){ui.modal={type:'request',id:a.slice(8)};render();return}if(a.startsWith('cart-plus:')||a.startsWith('cart-minus:')||a.startsWith('cart-remove:')){let id=+a.split(':')[1],i=state.cart.find(x=>x.id===id);if(!i)return;if(a.startsWith('cart-plus'))i.qty++;else if(a.startsWith('cart-minus'))i.qty--;else i.qty=0;state.cart=state.cart.filter(x=>x.qty>0);save();render();return}if(a.startsWith('reorder:')){let o=state.orders.find(x=>x.id===a.slice(8)),count=0;for(let i of o.items)if(add(i.id,i.qty,true))count++;ui.modal=null;ui.drawer='cart';toast(`${count} od ${o.items.length} artikala dodato u korpu.`);return}if(a.startsWith('order-status:')){let [,id,status]=a.split(':'),o=state.orders.find(x=>x.id===id);o.status=status;if(status==='Potvrđeno')o.erp='Čeka slanje';if(status==='Odbijeno')o.erp='Nije poslato';if(status==='Isporučeno'){let pa=state.partners.find(x=>x.id===o.partner);pa.debt+=o.total}state.activity.unshift(`${o.id}: ${status}`);save();ui.modal=null;toast(`Porudžbina ${id}: ${status}.`);return}if(a.startsWith('sync:')){let id=a.slice(5),o=state.orders.find(x=>x.id===id);if(o&&o.erp==='Čeka slanje'){o.erp='Sinhronizovano';state.activity.unshift(`${id}: simuliran ERP prijem`);save();ui.modal=null;toast(`${id} je označena kao sinhronizovana (demo).`)}return}if(a.startsWith('request-status:')){let parts=a.split(':'),r=state.requests.find(x=>x.id===parts[1]);r.status=parts.slice(2).join(':');save();ui.modal=null;toast(`Zahtev ${r.id}: ${r.status}.`);return}if(a==='sync-stock'){toast('Demo zalihe su osvežene. Nema aktivne ERP veze.');return}if(a==='download-stock-sample'){download('tehnogama-primer-zaliha.csv','SKU,kolicina\n10125990046,36\n10932010005,12','text/csv;charset=utf-8');return}if(a==='apply-stock-import'){let n=0;for(let row of ui.stockPreview)if(row.id){state.stock[row.id]=Math.max(0,row.qty);n++}ui.stockPreview=[];save();toast(`${n} stanja zaliha je ažurirano.`);return}if(a==='download-sample'){download('tehnogama-primer-porudzbine.csv','SKU,kolicina\n10125990046,4\n10321010002,8\n10932010005,12','text/csv;charset=utf-8');return}if(a.startsWith('download-spec:')){let p=P(+a.slice(14));download(`${p.sku}-demo-list.txt`,docSpec(p));return}if(a.startsWith('download-order:')){let id=a.slice(15),o=state.orders.find(x=>x.id===id);download(`${id}-demo-pregled.csv`,orderCsv(o),'text/csv;charset=utf-8');return}if(a==='preview-paste'){let text=document.getElementById('bulk-text')?.value||'';ui.importPreview=parseDelimited(text);ui.importName='Nalepljeni unos';if(!ui.importPreview.length)toast('Unesite redove u formatu SKU, količina.',true);else render();return}if(a==='apply-import'){let count=0,invalid=0;for(let row of ui.importPreview){if(row.id&&add(row.id,row.qty,true))count++;else invalid++}ui.importPreview=[];save();toast(`${count} artikala dodato u korpu${invalid?`; ${invalid} preskočeno (šifra, zaliha ili oprema na upit)`:''}.`);return}});
document.addEventListener('submit',e=>{let f=e.target;if(!f.id)return;e.preventDefault();let d=new FormData(f);if(f.id==='rules-form'){let q10=Number(d.get('q10')),q20=Number(d.get('q20')),q50=Number(d.get('q50'));if(q10>q20||q20>q50){toast('Rabat mora rasti sa količinom.',true);return}state.rules={q10,q20,q50};save();toast('Količinski rabati su ažurirani.');return}if(f.id==='quick-form'){let p=products.find(p=>p.sku.toLowerCase()===String(d.get('sku')).trim().toLowerCase());if(!p){toast('Šifra nije pronađena u katalogu.',true);return}add(p.id,Number(d.get('qty')));f.reset();return}if(f.id==='checkout-form'){let pa=partner(),total=state.cart.reduce((s,i)=>s+price(P(i.id),pa,i.qty)*i.qty,0);if(!state.cart.length)return;if(state.cart.some(i=>i.qty>stock(P(i.id)))){toast('Proverite raspoložive količine.',true);return}let last=Math.max(...state.orders.map(o=>+o.id.split('-')[1]||0)),id=`TG-${last+1}`,o={id,partner:pa.id,date:new Date().toISOString().slice(0,10),items:state.cart.map(i=>({...i})),total,status:'Na čekanju',erp:'Čeka odobrenje',po:String(d.get('po')).trim(),note:String(d.get('note')).trim(),delivery:String(d.get('delivery'))};state.orders.push(o);state.cart=[];state.page='orders';ui.drawer=null;save();toast(`Porudžbina ${id} je kreirana i čeka pregled (demo).`);return}if(f.id==='partner-form'){let pa=state.partners.find(p=>p.id===f.dataset.id);pa.discount=Math.max(0,Math.min(60,Number(d.get('discount'))));pa.limit=Math.max(0,Number(d.get('limit')));pa.debt=Math.max(0,Number(d.get('debt')));pa.status=String(d.get('status'));save();ui.modal=null;toast('Uslovi partnera su ažurirani.');return}if(f.id==='stock-form'){state.stock[f.dataset.id]=Math.max(0,Number(d.get('stock')));save();ui.modal=null;toast('Lager je ažuriran u demou.');return}if(f.id==='quote-form'||f.id==='service-form'){let service=f.id==='service-form',id=(service?'SRV-':'RFQ-')+(Math.max(1000,...state.requests.filter(r=>r.id.startsWith(service?'SRV':'RFQ')).map(r=>Number(r.id.split('-')[1])||1000))+1),r={id,type:service?'Servis':'Ponuda',partner:partner().id,subject:service?`${String(d.get('model')).trim()} · ${String(d.get('priority'))}`:String(d.get('subject')).trim(),date:new Date().toISOString().slice(0,10),status:'Novo',detail:service?`${String(d.get('location')).trim()} · ${String(d.get('details')).trim()}${d.get('attachment')?.name?' · Prilog: '+d.get('attachment').name:''}`:`${String(d.get('pressure')).trim()} · ${String(d.get('flow')).trim()} · ${String(d.get('timeline'))} · ${String(d.get('details')).trim()}`};state.requests.push(r);save();ui.modal=null;state.page='service';toast(`Zahtev ${id} je dodat u demo.`);return}});
document.addEventListener('change',e=>{let t=e.target;if(t.id==='brand-filter'){ui.brand=t.value;render()}if(t.id==='stock-filter'){ui.stock=t.value;render()}if(t.dataset.qty){let i=state.cart.find(x=>x.id===+t.dataset.qty);if(i){i.qty=Math.max(1,Math.floor(+t.value||1));save();render()}}if(t.id==='import-file'&&t.files[0])importFile(t.files[0]);if(t.id==='stock-import-file'&&t.files[0])importStockFile(t.files[0]);if(t.id==='order-attachment'&&t.files[0]){let file=t.files[0];let id='IMP-'+Date.now().toString().slice(-6);state.requests.push({id,type:'Uvoz porudžbine',partner:partner().id,subject:file.name,date:new Date().toISOString().slice(0,10),status:'Novo',detail:'Prilog za ručnu proveru · samo naziv fajla, bez otpremanja sadržaja'});save();toast('Dokument je evidentiran za pregled u demou.');}});
document.addEventListener('input',e=>{let t=e.target;if(t.id==='catalog-search'){let pos=t.selectionStart;ui.search=t.value;render();let next=document.getElementById('catalog-search');next?.focus();next?.setSelectionRange(pos,pos)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-product]')){e.preventDefault();ui.modal={type:'product',id:+e.target.dataset.product};render();return}if(e.key==='Escape'&&(ui.modal||ui.drawer||ui.roleMenu)){ui.modal=null;ui.drawer=null;ui.roleMenu=false;render()}if(e.key==='Enter'&&e.target.id==='global-search'){ui.search=e.target.value;ui.category='Sve';state.page='catalog';render()}});
function parseDelimited(text){let lines=text.replace(/^\ufeff/,'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean);return lines.map((line,index)=>{let sep=line.includes(';')?';':line.includes('\t')?'\t':',';let cells=line.split(sep).map(s=>s.replace(/^\s*['"]?|['"]?\s*$/g,'').trim());if(index===0&&/^(sku|sifra|šifra|product)/i.test(cells[0]))return null;return rowResult(cells[0],cells[1])}).filter(Boolean)}
function rowResult(sku,qty){let p=products.find(p=>p.sku.toLowerCase()===String(sku||'').trim().toLowerCase());return {sku:String(sku||'').trim(),qty:Math.max(1,Math.floor(Number(qty)||1)),id:p?.id||null}}
function parseXml(text){let xml=new DOMParser().parseFromString(text,'application/xml');if(xml.querySelector('parsererror'))throw Error('XML format nije ispravan.');let nodes=[...xml.querySelectorAll('item,row,product,artikal')];return nodes.map(n=>rowResult(n.querySelector('sku,sifra,šifra,code')?.textContent||n.getAttribute('sku'),n.querySelector('qty,kolicina,količina,quantity')?.textContent||n.getAttribute('qty'))).filter(x=>x.sku)}
async function unzipText(buffer,name){let b=new Uint8Array(buffer),v=new DataView(buffer),end=-1;for(let i=b.length-22;i>=Math.max(0,b.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('XLSX datoteka nije ispravna.');let offset=v.getUint32(end+16,true),count=v.getUint16(end+10,true);for(let i=0;i<count;i++){if(v.getUint32(offset,true)!==0x02014b50)break;let method=v.getUint16(offset+10,true),size=v.getUint32(offset+20,true),nl=v.getUint16(offset+28,true),el=v.getUint16(offset+30,true),cl=v.getUint16(offset+32,true),file=new TextDecoder().decode(b.slice(offset+46,offset+46+nl)),local=v.getUint32(offset+42,true);if(file===name){let start=local+30+v.getUint16(local+26,true)+v.getUint16(local+28,true),data=b.slice(start,start+size);if(method===0)return new TextDecoder().decode(data);if(method===8&&typeof DecompressionStream!=='undefined'){let stream=new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'));return new TextDecoder().decode(await new Response(stream).arrayBuffer())}throw Error('Ovaj XLSX način kompresije nije podržan.')}offset+=46+nl+el+cl}return null}
async function parseXlsx(file){let buf=await file.arrayBuffer(),shared=await unzipText(buf,'xl/sharedStrings.xml'),sheet=await unzipText(buf,'xl/worksheets/sheet1.xml');if(!sheet)throw Error('Nije pronađen prvi radni list.');let parser=new DOMParser(),strings=shared?[...parser.parseFromString(shared,'application/xml').getElementsByTagName('si')].map(n=>n.textContent):[],xml=parser.parseFromString(sheet,'application/xml'),rows=[...xml.getElementsByTagName('row')].map(row=>{let cells={};for(let c of row.getElementsByTagName('c')){let col=(c.getAttribute('r')||'').match(/^[A-Z]+/)?.[0]||'A',raw=c.getElementsByTagName('v')[0]?.textContent||c.getElementsByTagName('is')[0]?.textContent||'';cells[col]=c.getAttribute('t')==='s'?strings[Number(raw)]||'':raw}return cells});if(!rows.length)return [];let header=rows[0],cols=Object.entries(header),skuCol=cols.find(([,v])=>/^(sku|sifra|šifra|code)$/i.test(String(v).trim()))?.[0]||'A',qtyCol=cols.find(([,v])=>/^(kolicina|količina|qty|quantity)$/i.test(String(v).trim()))?.[0]||'B',hasHeader=/^(sku|sifra|šifra|code)$/i.test(String(header[skuCol]||'').trim());return rows.slice(hasHeader?1:0).map(r=>rowResult(r[skuCol],r[qtyCol])).filter(x=>x.sku)}
async function importStockFile(file){try{let ext=file.name.split('.').pop().toLowerCase(),rows=ext==='xlsx'?await parseXlsx(file):ext==='xml'?parseXml(await file.text()):['csv','txt'].includes(ext)?parseDelimited(await file.text()):null;if(!rows?.length)throw Error('Nisu pronađeni SKU i količina.');ui.stockPreview=rows.slice(0,80);ui.stockImportName=file.name;render();toast(`Pronađeno ${rows.length} redova za pregled.`)}catch(err){toast(`Uvoz zaliha nije uspeo: ${err.message}`,true)}}
async function importFile(file){try{let ext=file.name.split('.').pop().toLowerCase(),rows=ext==='xlsx'?await parseXlsx(file):ext==='xml'?parseXml(await file.text()):['csv','txt'].includes(ext)?parseDelimited(await file.text()):null;if(!rows)throw Error('Koristite CSV, TXT, XLSX ili XML.');if(!rows.length)throw Error('Nisu pronađeni SKU i količina.');ui.importPreview=rows.slice(0,80);ui.importName=file.name;render();toast(`Pronađeno ${rows.length} redova za pregled.`)}catch(err){toast(`Uvoz nije uspeo: ${err.message}`,true)}}
render();
